import { gql } from "~/gql";

// Operation names are global across erxes; keep the plugin prefix. gql() is
// generated by codegen — write documents as static strings (no `${}`), and
// let Apollo hooks infer their types from the document.

export const CLASS_LIST = gql(`
  query edureportClassList($term: String, $page: Int, $perPage: Int) {
    edureportClassList(term: $term, page: $page, perPage: $perPage) {
      totalCount
      list {
        _id
        name
        subject
        term
        grade
        studentCount
      }
    }
  }
`);

export const CLASS_DETAIL = gql(`
  query edureportClassDetail($_id: String!) {
    edureportClassDetail(_id: $_id) {
      _id
      name
      subject
      term
      grade
      teacherId
      atRiskAttendancePct
      atRiskScorePct
      studentCount
      createdAt
    }
  }
`);

export const CLASS_ADD = gql(`
  mutation edureportClassAdd($name: String!, $subject: String!, $term: String!, $grade: String) {
    edureportClassAdd(name: $name, subject: $subject, term: $term, grade: $grade) {
      _id
    }
  }
`);

export const CLASS_EDIT = gql(`
  mutation edureportClassEdit(
    $_id: String!
    $name: String
    $subject: String
    $term: String
    $grade: String
    $atRiskAttendancePct: Float
    $atRiskScorePct: Float
  ) {
    edureportClassEdit(
      _id: $_id
      name: $name
      subject: $subject
      term: $term
      grade: $grade
      atRiskAttendancePct: $atRiskAttendancePct
      atRiskScorePct: $atRiskScorePct
    ) {
      _id
      name
      subject
      term
      grade
      atRiskAttendancePct
      atRiskScorePct
    }
  }
`);

export const CLASS_REMOVE = gql(`
  mutation edureportClassRemove($_id: String!) {
    edureportClassRemove(_id: $_id)
  }
`);

export const STUDENT_LIST = gql(`
  query edureportStudentList($classId: String!) {
    edureportStudentList(classId: $classId) {
      _id
      name
      code
    }
  }
`);

export const STUDENTS_IMPORT = gql(`
  mutation edureportStudentsImport($classId: String!, $rows: [EdureportStudentRowInput!]!) {
    edureportStudentsImport(classId: $classId, rows: $rows) {
      inserted
      skippedCodes
      errors {
        row
        message
      }
    }
  }
`);

export const ATTENDANCE_SUMMARY = gql(`
  query edureportAttendanceSummary($classId: String!, $from: String!, $to: String!) {
    edureportAttendanceSummary(classId: $classId, from: $from, to: $to) {
      studentId
      rate
      absences
      lates
    }
  }
`);
